using System;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class RefinementTests
    {
        [Theory] [InlineData(1000,0,true,1000)] [InlineData(1000,0,false,0)] [InlineData(30000,0,true,0)] [InlineData(-2147483640,2147483640,true,16)] [InlineData(0,100,true,0)]
        public void NeedsClockHandlesPauseStallAndWrap(int now,int before,bool active,int expected)=>Assert.Equal(expected,NeedsRules.Delta(now,before,active));
        [Fact] public void MinuteOfNeedsIsIndependentOfFrameRate(){var a=new NeedsData();var b=new NeedsData();for(int i=0;i<60;i++)NeedsRules.Advance(a,1000,1,1,1,false);for(int i=0;i<600;i++)NeedsRules.Advance(b,100,1,1,1,false);Assert.InRange(a.Hunger,98.999f,99.001f);Assert.InRange(a.Sleep,99.332f,99.335f);Assert.InRange(Math.Abs(a.Hunger-b.Hunger),0,.005f);}
        [Fact] public void InvalidRatesCannotAddFoodOrCorruptPercent(){var d=new NeedsData();NeedsRules.Advance(d,1000,float.NaN,-1,float.PositiveInfinity,false);Assert.True(NeedsRules.Percent(d.Hunger));Assert.True(NeedsRules.Percent(d.Thirst));Assert.True(d.Hunger<100);NeedsRules.Advance(d,100000,1,1,1,false);Assert.True(d.Hunger>99);}
        [Fact] public void RestRestoresEnergyWithoutRefillingFood(){var d=new NeedsData{Sleep=50,Hunger=50,Thirst=50};for(int i=0;i<60;i++)NeedsRules.Advance(d,1000,1,1,1,true);Assert.InRange(d.Sleep,59.99f,60.01f);Assert.InRange(d.Hunger,48.99f,49.01f);}
        [Theory] [InlineData(200,200,100f)] [InlineData(150,200,50f)] [InlineData(100,200,0f)] [InlineData(50,100,50f)] [InlineData(300,200,100f)]
        public void HealthGaugeMatchesActualUsableHealth(int health,int max,float expected)=>Assert.Equal(expected,NeedsRules.Health(health,max));
        [Fact] public void StaminaDrainsWithSleepAndEnforcesCooldown(){var rested=new NeedsData();var tired=new NeedsData{Sleep=0};for(int i=0;i<10;i++){NeedsRules.Stamina(rested,1000,true,true);NeedsRules.Stamina(tired,1000,true,true);}Assert.InRange(rested.Stamina,64.99f,65.01f);Assert.InRange(tired.Stamina,29.99f,30.01f);for(int i=0;i<5;i++)NeedsRules.Stamina(tired,1000,true,true);Assert.Equal(0,tired.Stamina);Assert.True(tired.StaminaCooldown>0);float before=tired.Stamina;NeedsRules.Stamina(tired,1000,false,false);Assert.True(tired.Stamina>before);}
        [Fact] public void StaminaRegenAndSmallFramesAreBounded(){var a=new NeedsData{Stamina=0};var b=new NeedsData{Stamina=0};for(int i=0;i<5;i++)NeedsRules.Stamina(a,1000,false,false);for(int i=0;i<50;i++)NeedsRules.Stamina(b,100,false,false);Assert.Equal(75,a.Stamina,2);Assert.Equal(a.Stamina,b.Stamina,2);NeedsRules.Stamina(a,30000,false,false);Assert.Equal(75,a.Stamina,2);}
        [Fact] public void FoodReceiptRemovesExactlyOneItemAndKeepsContainersMetadata(){var inv=new InvData{Items=new Dictionary<string,int>{{"water",2}},Extra=new Dictionary<string,JToken>{{"Future",42}}};inv.Containers["home"]=new Dictionary<string,int>{{"water",3}};var needs=new NeedsData{Thirst=10};var receipt=NeedsRules.Food(needs,"receipt",0,35);var next=NeedsRules.Consume(inv,new ItemDef{Id="water"},receipt);Assert.Equal(2,inv.Items["water"]);Assert.Equal(1,next.Items["water"]);Assert.Equal(3,next.Containers["home"]["water"]);Assert.Equal(42,(int)next.Extra["Future"]);Assert.Equal(45,next.Consumption.Thirst);Assert.Equal(10,needs.Thirst);}
        [Fact] public void ConsumptionRecoveryNeverRefillsAgainAfterAcknowledgment(){var d=new NeedsData{Thirst=10};var receipt=NeedsRules.Food(d,"one",0,35);Assert.True(NeedsRules.Apply(ref d,receipt,n=>Assert.Equal("one",n.LastConsumptionId)));Assert.Equal(45,d.Thirst);d.Thirst=40;Assert.True(NeedsRules.Apply(ref d,receipt,n=>throw new Exception()));Assert.Equal(40,d.Thirst);var reload=JsonConvert.DeserializeObject<NeedsData>(JsonConvert.SerializeObject(d));Assert.True(NeedsRules.Apply(ref reload,receipt,n=>throw new Exception()));Assert.Equal(40,reload.Thirst);}
        [Fact] public void NeedsWriteFailureLeavesEffectPendingAndMemoryUnchanged(){var d=new NeedsData{Thirst=10,Extra=new Dictionary<string,JToken>{{"Future",true}}};var old=d;var receipt=NeedsRules.Food(d,"one",0,35);Assert.Throws<InvalidOperationException>(()=>NeedsRules.Apply(ref d,receipt,n=>throw new InvalidOperationException()));Assert.Same(old,d);Assert.Equal(10,d.Thirst);Assert.True(NeedsRules.Apply(ref d,receipt,n=>{}));Assert.Equal(45,d.Thirst);Assert.True((bool)d.Extra["Future"]);}
        [Theory] [InlineData(float.NaN,1)] [InlineData(1,float.PositiveInfinity)] [InlineData(101,0)]
        public void InvalidItemEffectsDoNotCreateReceipt(float hunger,float thirst)=>Assert.Null(NeedsRules.Food(new NeedsData(),"one",hunger,thirst));
        [Fact] public void MissingItemDoesNotGrantBenefits(){Assert.Null(NeedsRules.Consume(new InvData(),new ItemDef{Id="missing"},NeedsRules.Food(new NeedsData(),"one",10,0)));}
        [Fact] public void PresetEnablesRoleplayButDoesNotTouchMoneyItemsOrLicences(){var w=new WalletData{Bank=1234,Cash=42,Dmv=new DmvData()};var dmv=w.Dmv;Assert.True(RoleplayDefaults.Wallet(w,()=>{}));Assert.True(w.Traffic.Enabled && w.Traffic.PursuitEnabled && w.Traffic.AdvancedOffences && w.Traffic.BribesEnabled && w.Traffic.BoloEnabled && w.Custody.Enabled);Assert.Equal(1234,w.Bank);Assert.Equal(42,w.Cash);Assert.Same(dmv,w.Dmv);Assert.Equal(1,w.RoleplayVersion);w.Traffic.Enabled=false;Assert.True(RoleplayDefaults.Wallet(w,()=>throw new Exception()));Assert.False(w.Traffic.Enabled);}
        [Fact] public void WalletPresetRollsBackAndProtectsPendingOrInvalidRecords(){var w=new WalletData{Bank=100};Assert.Throws<InvalidOperationException>(()=>RoleplayDefaults.Wallet(w,()=>throw new InvalidOperationException()));Assert.Null(w.Traffic);Assert.Null(w.Custody);Assert.Equal(0,w.RoleplayVersion);w.Traffic=new TrafficData{Issued=-1};Assert.False(RoleplayDefaults.Wallet(w,()=>throw new Exception()));Assert.Equal(-1,w.Traffic.Issued);}
        [Fact] public void GangPresetPreservesOwnershipReputationAndExplicitLaterChoice(){var s=new GangState{Gang="Mine",Reputation=700,Rank=2,Extra=new Dictionary<string,JToken>{{"Future",true}}};Assert.True(RoleplayDefaults.Gang(s,n=>{},out var next));Assert.Equal(0,s.RoleplayVersion);Assert.True(next.PresenceEnabled && next.TerritoriesEnabled && next.Warfare.AttacksEnabled && next.Warfare.RivalsEnabled && next.Warfare.Reinforcements && next.DriveBys.Enabled);Assert.Equal(700,next.Reputation);Assert.Equal("Mine",next.Gang);Assert.True((bool)next.Extra["Future"]);next.PresenceEnabled=false;Assert.True(RoleplayDefaults.Gang(next,n=>throw new Exception(),out var same));Assert.Same(next,same);Assert.False(same.PresenceEnabled);}
        [Fact] public void GangPresetFailureDoesNotMutateOriginal(){var s=new GangState{Reputation=12};Assert.Throws<InvalidOperationException>(()=>RoleplayDefaults.Gang(s,n=>throw new InvalidOperationException(),out _));Assert.False(s.PresenceEnabled);Assert.Null(s.Warfare);Assert.Equal(12,s.Reputation);}
        [Theory] [InlineData(true)] [InlineData(false)]
        public void BankTransferConservesFundsAndRollsBackOnDiskFailure(bool deposit){var w=new WalletData{Bank=1000};int cash=500;Assert.True(BankTransfer.Commit(w,()=>cash,n=>cash=n,100,deposit,()=>{}));Assert.Equal(1500,w.Bank+cash);int bank=w.Bank,held=cash;Assert.Throws<InvalidOperationException>(()=>BankTransfer.Commit(w,()=>cash,n=>cash=n,100,deposit,()=>throw new InvalidOperationException()));Assert.Equal(bank,w.Bank);Assert.Equal(held,cash);}
        [Theory] [InlineData(0)] [InlineData(-1)] [InlineData(10000)]
        public void InvalidOrUnaffordableBankTransferDoesNothing(int amount){var w=new WalletData{Bank=1000};int cash=500;Assert.False(BankTransfer.Commit(w,()=>cash,n=>cash=n,amount,true,()=>throw new Exception()));Assert.Equal(1000,w.Bank);Assert.Equal(500,cash);}
        [Fact] public void BankOverflowIsRejected(){var w=new WalletData{Bank=int.MaxValue};int cash=100;Assert.False(BankTransfer.Commit(w,()=>cash,n=>cash=n,100,true,()=>throw new Exception()));}
        [Fact] public void RealFilesRecoverCommittedConsumptionExactlyOnce()
        {
            string dir=System.IO.Path.Combine(System.IO.Path.GetTempPath(),Guid.NewGuid().ToString("N"));System.IO.Directory.CreateDirectory(dir);
            try{var files=new JsonFiles();string ip=System.IO.Path.Combine(dir,"Inventory.json"),np=System.IO.Path.Combine(dir,"Needs.json");var inv=new InvData{Items=new Dictionary<string,int>{{"water",2}}};var d=new NeedsData{Thirst=10};files.Write(np,d);var receipt=NeedsRules.Food(d,"durable",0,35);files.Write(ip,NeedsRules.Consume(inv,new ItemDef{Id="water"},receipt));Assert.Throws<InvalidOperationException>(()=>NeedsRules.Apply(ref d,receipt,n=>throw new InvalidOperationException("disk")));
            var restored=files.Read<InvData>(ip,()=>null);d=files.Read<NeedsData>(np,()=>null);Assert.Equal(1,restored.Items["water"]);Assert.Equal(10,d.Thirst);Assert.True(NeedsRules.Apply(ref d,restored.Consumption,n=>files.Write(np,n)));d=files.Read<NeedsData>(np,()=>null);Assert.Equal(45,d.Thirst);d.Thirst=40;files.Write(np,d);Assert.True(NeedsRules.Apply(ref d,restored.Consumption,n=>throw new Exception()));Assert.Equal(40,d.Thirst);}
            finally{System.IO.Directory.Delete(dir,true);}
        }
        [Fact] public void SuspendedTrafficKeepsTicketAndFundsWhenPresetActivates()
        {
            var w=new WalletData{Bank=1234};TrafficTransactions.Configure(w,true,()=>{},out _);var t=new TrafficTicket{Id="old",Street="Alta",Model=123,Plate="OLD",Lines=new System.Collections.Generic.List<TrafficLine>{new TrafficLine{Code=TrafficOffence.NoSeatbelt,Amount=150}}};TrafficTransactions.Begin(w,t,()=>{},out _);string before=JsonConvert.SerializeObject(w.Traffic.Tickets[0]);Assert.True(RoleplayDefaults.Wallet(w,()=>{}));Assert.Equal(before,JsonConvert.SerializeObject(w.Traffic.Tickets[0]));Assert.Equal("old",w.Traffic.Pending);Assert.Null(w.Traffic.Tickets[0].Pursuit);TrafficTransactions.Finish(w,"old","served",()=>{},out _);Assert.True(RoleplayDefaults.Wallet(w,()=>throw new Exception()));Assert.Equal(1234,w.Bank);Assert.Equal(150,w.Traffic.Tickets[0].Total);Assert.False(w.Traffic.Tickets[0].Paid);
        }
        [Fact] public void CorruptGangJournalDefersUpgradeInsteadOfReplacingIt(){var s=new GangState{Loyalty=new GangLoyaltyData{Completed=-1}};Assert.False(RoleplayDefaults.Gang(s,n=>throw new Exception(),out _));Assert.Equal(-1,s.Loyalty.Completed);Assert.Equal(0,s.RoleplayVersion);}
        [Fact] public void TwentyFourSlotMigrationKeepsLegacyLastSlotAndAllQuantities(){var slots=new System.Collections.Generic.List<string>(new string[25]);slots[24]="water";var result=InventoryLayout.Reconcile(slots,new[]{"water"},24);Assert.Equal(48,result.Count);Assert.Equal("water",result[24]);Assert.Equal(result,InventoryLayout.Reconcile(result,new[]{"water"},24));}
        [Fact] public void CurrentGridMatchesSixColumnsFourRows(){var cells=System.Linq.Enumerable.Range(0,24).Select(RoleplayInventoryLayout.Cell).ToArray();Assert.Equal(6,cells.Select(c=>c.X).Distinct().Count());Assert.Equal(4,cells.Select(c=>c.Y).Distinct().Count());Assert.All(cells,c=>{Assert.InRange(c.X,140,790);Assert.InRange(c.Bottom,370,760);});}
        [Fact] public void EmptyInventoryAndNewPageAreStable(){Assert.Equal(24,InventoryLayout.Reconcile(null,Array.Empty<string>(),24).Count);Assert.Equal(48,InventoryLayout.Reconcile(null,System.Linq.Enumerable.Range(0,25).Select(i=>"item"+i),24).Count);}
        [Fact] public void OldEmptyPaddingDoesNotCreateAnExtraPage(){Assert.Equal(24,InventoryLayout.Reconcile(new string[25],Array.Empty<string>(),24).Count);}
        [Fact] public void LastItemOnSecondPageKeepsItsSavedPosition(){var slots=new string[48];slots[47]="water";var next=InventoryLayout.Reconcile(slots,new[]{"water"},24);Assert.Equal(48,next.Count);Assert.Equal("water",next[47]);}
        [Fact] public void DiscardSaveFailureKeepsItemAndReceipt(){var inv=new InvData{Items=new Dictionary<string,int>{{"water",2}},Consumption=new NeedsConsumption{Id="ack",Hunger=50,Thirst=50,Sleep=50}};string before=JsonConvert.SerializeObject(inv);Assert.Throws<InvalidOperationException>(()=>InventoryEdits.Drop(ref inv,"water",2,n=>throw new InvalidOperationException()));Assert.Equal(before,JsonConvert.SerializeObject(inv));Assert.True(InventoryEdits.Drop(ref inv,"water",1,n=>{}));Assert.Equal(1,inv.Items["water"]);Assert.Equal("ack",inv.Consumption.Id);}
        [Fact] public void MoveSaveFailureKeepsSavedLayout(){var inv=new InvData{Items=new Dictionary<string,int>{{"water",1}},GridSlots=new System.Collections.Generic.List<string>{"water",null}};Assert.Throws<InvalidOperationException>(()=>InventoryEdits.Move(ref inv,0,1,n=>throw new InvalidOperationException()));Assert.Equal("water",inv.GridSlots[0]);Assert.True(InventoryEdits.Move(ref inv,0,1,n=>{}));Assert.Equal("water",inv.GridSlots[1]);Assert.Equal(1,inv.Items["water"]);}
        [Fact] public void InvalidDiscardCannotRemoveAnything(){var inv=new InvData{Items=new Dictionary<string,int>{{"water",1}}};Assert.False(InventoryEdits.Drop(ref inv,"water",2,n=>throw new Exception()));Assert.False(InventoryEdits.Drop(ref inv,"water",-1,n=>throw new Exception()));Assert.False(InventoryEdits.Move(ref inv,-1,0,n=>throw new Exception()));Assert.Equal(1,inv.Items["water"]);}
    }
}
